package com.akashpriya.wedding.controller;

import com.akashpriya.wedding.config.WeddingProperties;
import com.akashpriya.wedding.constants.AppConstants;
import com.akashpriya.wedding.service.EventService;
import com.akashpriya.wedding.service.FamilyService;
import com.akashpriya.wedding.service.GalleryService;
import com.akashpriya.wedding.service.HotelService;
import com.akashpriya.wedding.service.MemoryWallService;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;

import java.time.format.DateTimeFormatter;

/**
 * Serves the single-page public wedding website with all sections.
 */
@Controller
public class HomeController {

    private final EventService eventService;
    private final HotelService hotelService;
    private final GalleryService galleryService;
    private final FamilyService familyService;
    private final MemoryWallService memoryWallService;
    private final WeddingProperties weddingProperties;

    public HomeController(EventService eventService, HotelService hotelService, GalleryService galleryService,
                           FamilyService familyService, MemoryWallService memoryWallService,
                           WeddingProperties weddingProperties) {
        this.eventService = eventService;
        this.hotelService = hotelService;
        this.galleryService = galleryService;
        this.familyService = familyService;
        this.memoryWallService = memoryWallService;
        this.weddingProperties = weddingProperties;
    }

    @GetMapping("/")
    public String home(Model model) {
        model.addAttribute("events", eventService.getAllEvents());
        model.addAttribute("hotels", hotelService.getAllHotels());
        model.addAttribute("galleryImages", galleryService.getAllImages());

        model.addAttribute("akashFamilyIntro", familyService.getIntroductionMembers(AppConstants.SIDE_AKASH));
        model.addAttribute("priyaFamilyIntro", familyService.getIntroductionMembers(AppConstants.SIDE_PRIYA));

        model.addAttribute("akashFamilyTree", familyService.getFamilyTree(AppConstants.SIDE_AKASH));
        model.addAttribute("priyaFamilyTree", familyService.getFamilyTree(AppConstants.SIDE_PRIYA));

        model.addAttribute("memoryPosts", memoryWallService.getApprovedPosts());

        String weddingDateIso = weddingProperties.getDate() != null
                ? weddingProperties.getDate().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
                : null;
        model.addAttribute("weddingDateIso", weddingDateIso);
        model.addAttribute("weddingDateDisplay", weddingProperties.getDate());

        return "index";
    }
}

package com.akashpriya.wedding.controller;

import com.akashpriya.wedding.config.WeddingProperties;
import com.akashpriya.wedding.constants.AppConstants;
import com.akashpriya.wedding.service.EventService;
import com.akashpriya.wedding.service.FamilyService;
import com.akashpriya.wedding.service.GalleryService;
import com.akashpriya.wedding.service.HotelService;
import com.akashpriya.wedding.service.MemoryWallService;
import org.springframework.core.io.ClassPathResource;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.GetMapping;

import java.time.format.DateTimeFormatter;

/**
 * Serves the single-page public wedding website with all sections.
 */
@Controller
public class HomeController {

    private static final String MUSIC_CLASSPATH_LOCATION = "static/audio/wedding-instrumental.mp3";

    private final EventService eventService;
    private final HotelService hotelService;
    private final GalleryService galleryService;
    private final FamilyService familyService;
    private final MemoryWallService memoryWallService;
    private final WeddingProperties weddingProperties;

    public HomeController(EventService eventService, HotelService hotelService, GalleryService galleryService,
                           FamilyService familyService, MemoryWallService memoryWallService,
                           WeddingProperties weddingProperties) {
        this.eventService = eventService;
        this.hotelService = hotelService;
        this.galleryService = galleryService;
        this.familyService = familyService;
        this.memoryWallService = memoryWallService;
        this.weddingProperties = weddingProperties;
    }

    @GetMapping("/")
    public String home(Model model) {
        model.addAttribute("events", eventService.getAllEvents());
        model.addAttribute("hotels", hotelService.getAllHotels());
        model.addAttribute("galleryImages", galleryService.getAllImages());

        model.addAttribute("akashFamilyIntro", familyService.getIntroductionMembers(AppConstants.SIDE_AKASH));
        model.addAttribute("priyaFamilyIntro", familyService.getIntroductionMembers(AppConstants.SIDE_PRIYA));

        model.addAttribute("akashFamilyTree", familyService.getFamilyTree(AppConstants.SIDE_AKASH));
        model.addAttribute("priyaFamilyTree", familyService.getFamilyTree(AppConstants.SIDE_PRIYA));

        model.addAttribute("memoryPosts", memoryWallService.getApprovedPosts());

        String weddingDateIso = weddingProperties.getDate() != null
                ? weddingProperties.getDate().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
                : null;
        model.addAttribute("weddingDateIso", weddingDateIso);
        model.addAttribute("weddingDateDisplay", weddingProperties.getDate());

        // Music toggle is only rendered if the optional instrumental track actually exists,
        // so the UI never shows a control for a missing/broken audio file.
        model.addAttribute("musicAvailable", new ClassPathResource(MUSIC_CLASSPATH_LOCATION).exists());

        return "index";
    }
}

/**
 * Circular ring countdown timer to the wedding date.
 * Reads the ISO date/time from the #countdownTimer element's data-wedding-date attribute
 * (populated server-side from application.yaml's wedding.date property).
 */
(function () {
  const countdownEl = document.getElementById('countdownTimer');
  if (!countdownEl) return;

  const weddingDateStr = countdownEl.getAttribute('data-wedding-date');
  if (!weddingDateStr) return;

  const weddingDate = new Date(weddingDateStr).getTime();

  const daysEl = document.getElementById('cd-days');
  const hoursEl = document.getElementById('cd-hours');
  const minutesEl = document.getElementById('cd-minutes');
  const secondsEl = document.getElementById('cd-seconds');

  const ringDays = document.getElementById('ring-days');
  const ringHours = document.getElementById('ring-hours');
  const ringMinutes = document.getElementById('ring-minutes');
  const ringSeconds = document.getElementById('ring-seconds');

  const RADIUS = 52;
  const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

  [ringDays, ringHours, ringMinutes, ringSeconds].forEach(function (ring) {
    if (ring) {
      ring.style.strokeDasharray = CIRCUMFERENCE.toFixed(2);
    }
  });

  // Capture the total day span once, so the days ring shows real progress toward the wedding.
  const initialDistance = weddingDate - new Date().getTime();
  const initialTotalDays = Math.max(1, Math.ceil(initialDistance / (1000 * 60 * 60 * 24)));

  function setRingProgress(ring, fraction) {
    if (!ring) return;
    const clamped = Math.max(0, Math.min(1, fraction));
    const offset = CIRCUMFERENCE * (1 - clamped);
    ring.style.strokeDashoffset = offset.toFixed(2);
  }

  function update() {
    const now = new Date().getTime();
    const distance = weddingDate - now;

    if (distance < 0) {
      daysEl.textContent = '00';
      hoursEl.textContent = '00';
      minutesEl.textContent = '00';
      secondsEl.textContent = '00';
      [ringDays, ringHours, ringMinutes, ringSeconds].forEach(function (ring) {
        setRingProgress(ring, 0);
      });
      clearInterval(timer);
      return;
    }

    const days = Math.floor(distance / (1000 * 60 * 60 * 24));
    const hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((distance % (1000 * 60)) / 1000);

    daysEl.textContent = String(days).padStart(2, '0');
    hoursEl.textContent = String(hours).padStart(2, '0');
    minutesEl.textContent = String(minutes).padStart(2, '0');
    secondsEl.textContent = String(seconds).padStart(2, '0');

    setRingProgress(ringDays, days / initialTotalDays);
    setRingProgress(ringHours, hours / 24);
    setRingProgress(ringMinutes, minutes / 60);
    setRingProgress(ringSeconds, seconds / 60);
  }

  update();
  const timer = setInterval(update, 1000);
})();

/**
 * countdown.js — premium glass countdown to the wedding date.
 *
 * Reads the ISO date/time from #countdownTimer's data-wedding-date attribute
 * (populated server-side from application.yaml's wedding.date). This is the single
 * source of truth — the date is never hardcoded here.
 *
 * Features / edge cases handled:
 *   - Single setInterval (no duplicate timers).
 *   - Subtle cross-fade only on the digits that actually change (no full-card flip).
 *   - Fixed-width digit containers to avoid layout shift.
 *   - Invalid date  -> shows a graceful message.
 *   - Already completed -> "The celebration has begun."
 *   - JS disabled -> static "00" placeholders remain visible (in the HTML).
 */
(function () {
  'use strict';

  var reduceMotion = window.matchMedia &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  document.addEventListener('DOMContentLoaded', function () {
    var root = document.getElementById('countdownTimer');
    if (!root) return;

    var weddingDateStr = root.getAttribute('data-wedding-date');
    var completeMsg = document.getElementById('countdownComplete');

    if (!weddingDateStr) {
      showComplete(root, completeMsg, 'Wedding date coming soon.');
      return;
    }

    var weddingDate = new Date(weddingDateStr).getTime();
    if (isNaN(weddingDate)) {
      showComplete(root, completeMsg, 'Wedding date coming soon.');
      return;
    }

    var units = {
      days: document.getElementById('cd-days'),
      hours: document.getElementById('cd-hours'),
      minutes: document.getElementById('cd-minutes'),
      seconds: document.getElementById('cd-seconds')
    };

    var last = { days: null, hours: null, minutes: null, seconds: null };
    var timer = null;

    function render() {
      var distance = weddingDate - Date.now();

      if (distance <= 0) {
        setDigit(units.days, '00');
        setDigit(units.hours, '00');
        setDigit(units.minutes, '00');
        setDigit(units.seconds, '00');
        if (timer) { clearInterval(timer); timer = null; }
        showComplete(root, completeMsg, 'The celebration has begun.');
        return;
      }

      var days = Math.floor(distance / 86400000);
      var hours = Math.floor((distance % 86400000) / 3600000);
      var minutes = Math.floor((distance % 3600000) / 60000);
      var seconds = Math.floor((distance % 60000) / 1000);

      updateUnit('days', pad(days));
      updateUnit('hours', pad(hours));
      updateUnit('minutes', pad(minutes));
      updateUnit('seconds', pad(seconds));
    }

    function updateUnit(key, value) {
      if (last[key] === value) return; // only touch DOM when it changes
      last[key] = value;
      setDigit(units[key], value);
    }

    function setDigit(el, value) {
      if (!el) return;
      el.textContent = value;
      if (!reduceMotion) {
        el.classList.remove('countdown-digit-swap');
        void el.offsetWidth; // force reflow so the animation retriggers
        el.classList.add('countdown-digit-swap');
      }
    }

    render();
    timer = setInterval(render, 1000);

    // Pause the ticking when the tab is hidden; resume + resync when visible.
    document.addEventListener('visibilitychange', function () {
      if (document.hidden) {
        if (timer) { clearInterval(timer); timer = null; }
      } else if (!timer) {
        render();
        timer = setInterval(render, 1000);
      }
    });
  });

  function pad(n) { return String(n).padStart(2, '0'); }

  function showComplete(root, msgEl, message) {
    if (root) root.style.display = 'none';
    if (msgEl) {
      msgEl.textContent = message;
      msgEl.hidden = false;
    }
  }
})();

/**
 * intro.js — Om opening splash experience.
 *
 * Responsibilities:
 *  - Show a full-screen Om splash once per browser tab/session (sessionStorage).
 *  - Generate a small number of lightweight golden floating particles.
 *  - Handle "Enter Celebration" and "Skip intro" — both perform the same clean exit:
 *      fade + slight scale up, restore scrolling, remove from AT/keyboard nav,
 *      reveal the hero underneath, WITHOUT reloading the page.
 *  - Respect prefers-reduced-motion (no particle animation, near-instant reveal).
 *  - Dev switch to disable the "show once per session" behaviour while testing.
 *
 * No page reload is ever triggered.
 */
(function () {
  'use strict';

  // ---- Development switch -------------------------------------------------
  // Set to true while testing to force the intro to show on EVERY load.
  var DEV_ALWAYS_SHOW_INTRO = false;

  var SESSION_KEY = 'omIntroSeen';

  var reduceMotion = window.matchMedia &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  document.addEventListener('DOMContentLoaded', function () {
    var splash = document.getElementById('omSplash');
    if (!splash) {
      // No splash element in DOM — nothing to do; ensure scrolling is enabled.
      document.body.classList.remove('intro-lock-scroll');
      return;
    }

    var alreadySeen = !DEV_ALWAYS_SHOW_INTRO &&
      sessionStorage.getItem(SESSION_KEY) === 'true';

    if (alreadySeen) {
      // Skip straight to the hero on refresh within the same session.
      removeSplashImmediately(splash);
      return;
    }

    // Show the splash: lock scrolling while it is visible.
    document.body.classList.add('intro-lock-scroll');

    if (!reduceMotion) {
      spawnParticles(splash);
    }

    var enterBtn = document.getElementById('enterCelebrationBtn');
    var skipBtn = document.getElementById('skipIntroBtn');

    if (enterBtn) enterBtn.addEventListener('click', function () { closeSplash(splash); });
    if (skipBtn) skipBtn.addEventListener('click', function () { closeSplash(splash); });

    // Allow Escape to skip the intro for keyboard users.
    document.addEventListener('keydown', function onEsc(e) {
      if (e.key === 'Escape' && !splash.classList.contains('om-splash-hidden')) {
        closeSplash(splash);
        document.removeEventListener('keydown', onEsc);
      }
    });

    // Move focus to the primary action for keyboard users.
    if (enterBtn && typeof enterBtn.focus === 'function') {
      window.setTimeout(function () { enterBtn.focus(); }, 100);
    }
  });

  /**
   * Creates a limited number of soft golden particles that drift slowly upward.
   * Fewer particles on small screens for performance. Particles are removed
   * from the DOM when the splash closes (see closeSplash).
   */
  function spawnParticles(splash) {
    var layer = splash.querySelector('.om-particles');
    if (!layer) return;

    var isMobile = window.matchMedia('(max-width: 768px)').matches;
    var count = isMobile ? 8 : 16;

    for (var i = 0; i < count; i++) {
      var p = document.createElement('span');
      p.className = 'om-particle';
      var size = 3 + Math.random() * 4;
      p.style.width = size + 'px';
      p.style.height = size + 'px';
      p.style.left = Math.random() * 100 + '%';
      p.style.setProperty('--particle-drift', (Math.random() * 60 - 30) + 'px');
      var duration = 7 + Math.random() * 6;
      p.style.animationDuration = duration + 's';
      p.style.animationDelay = (Math.random() * duration) + 's';
      layer.appendChild(p);
    }
  }

  /**
   * Cleanly closes the splash: fade + slight scale up, then hide entirely.
   * Restores scrolling, records the session flag, and removes it from AT/keyboard nav.
   */
  function closeSplash(splash) {
    if (splash.classList.contains('om-splash-exit')) return; // already closing

    try { sessionStorage.setItem(SESSION_KEY, 'true'); } catch (e) { /* ignore */ }

    splash.classList.add('om-splash-exit');
    splash.setAttribute('aria-hidden', 'true');

    var finalize = function () {
      splash.classList.add('om-splash-hidden');
      document.body.classList.remove('intro-lock-scroll');
      // Remove particles to avoid running animations / memory leaks.
      var layer = splash.querySelector('.om-particles');
      if (layer) layer.innerHTML = '';
      // Notify the rest of the app that the celebration has been entered.
      document.dispatchEvent(new CustomEvent('celebration:entered'));
    };

    if (reduceMotion) {
      finalize();
    } else {
      var done = false;
      var onEnd = function () {
        if (done) return;
        done = true;
        splash.removeEventListener('transitionend', onEnd);
        finalize();
      };
      splash.addEventListener('transitionend', onEnd);
      // Fallback in case transitionend doesn't fire.
      window.setTimeout(onEnd, 1300);
    }
  }

  /** Removes the splash with no animation (used when already seen this session). */
  function removeSplashImmediately(splash) {
    splash.classList.add('om-splash-hidden');
    splash.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('intro-lock-scroll');
    var layer = splash.querySelector('.om-particles');
    if (layer) layer.innerHTML = '';
    // Still signal entered so music button etc. can appear.
    document.dispatchEvent(new CustomEvent('celebration:entered'));
  }
})();
